insert into public.player_tags (player_id, tag_id)
select p.id, t.id
from public.players p
cross join public.tags t
where t.slug = 'esp-euro-2008'
	and p.metadata ->> 'dev_seed_id' like 'espeuro08-%'
on conflict do nothing;

